package com.example.demo.employee;

import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;
import static org.springframework.http.HttpStatus.NOT_FOUND;

@Service
public class OwnedEmployeeService {
    private final EmployeeRepository employees;

    public OwnedEmployeeService(EmployeeRepository employees) {
        this.employees = employees;
    }

    @PreAuthorize("isAuthenticated()")
    public Employee create(String name, String department) {
        return employees.save(
            new Employee(name, department, currentUsername()));
    }

    @PreAuthorize("isAuthenticated()")
    public Employee read(Long id) {
        return employees.findByIdAndOwnerUsername(id, currentUsername())
            .orElseThrow(() ->
                new ResponseStatusException(NOT_FOUND));
    }

    private String currentUsername() {
        return SecurityContextHolder.getContext()
            .getAuthentication().getName();
    }
}

package com.example.demo.employee;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
@Entity
public class Employee {
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;
    @Column(nullable = false) private String name;
    @Column(nullable = false) private String department;
    @Column(name = "owner_username", nullable = false, updatable = false, length = 100)
    private String ownerUsername;
    protected Employee() {}
    public Employee(String name, String department, String ownerUsername) {
        this.name = name;
        this.department = department;
        this.ownerUsername = ownerUsername;
    }
    public Long getId() { return id; }
    public String getName() { return name; }
    public String getDepartment() { return department; }
}

package com.example.demo.employee;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
public interface EmployeeRepository extends JpaRepository<Employee, Long> {
    Optional<Employee> findByIdAndOwnerUsername(Long id, String ownerUsername);
}

package com.example.demo.employee;
import org.springframework.web.bind.annotation.*;
@RestController
@RequestMapping("/employees")
public class EmployeeController {
    private final OwnedEmployeeService service;
    public EmployeeController(OwnedEmployeeService service) { this.service = service; }
    public record EmployeeRequest(String name, String department) {}
    @PostMapping
    public Employee create(@RequestBody EmployeeRequest request) {
        return service.create(request.name(), request.department());
    }
    @GetMapping("/{id}")
    public Employee read(@PathVariable("id") Long id) { return service.read(id); }
}

package com.example.demo;

import org.springframework.security.web.csrf.CsrfToken;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class CsrfController {
    @GetMapping("/csrf")
    CsrfResponse csrf(CsrfToken token) {
        return new CsrfResponse(
            token.getHeaderName(), token.getToken());
    }

    record CsrfResponse(String headerName, String token) {}
}

package com.example.demo;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.Customizer;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.core.userdetails.User;
import org.springframework.security.core.userdetails.UserDetailsService;
import org.springframework.security.crypto.factory.PasswordEncoderFactories;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.provisioning.InMemoryUserDetailsManager;
import org.springframework.security.web.SecurityFilterChain;

@Configuration
@org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity
public class SecurityConfig {
    @Bean
    PasswordEncoder passwordEncoder() {
        return PasswordEncoderFactories.createDelegatingPasswordEncoder();
    }

    @Bean
    UserDetailsService users(
            PasswordEncoder encoder,
            @Value("${DEMO_USER_PASSWORD}") String password) {
        return new InMemoryUserDetailsManager(
            User.withUsername("reader")
                .password(encoder.encode(password))
                .roles("USER")
                .build());
    }

    @Bean
    SecurityFilterChain security(HttpSecurity http) throws Exception {
        return http
            .authorizeHttpRequests(rules -> rules
                .requestMatchers("/csrf").authenticated()
                .requestMatchers("/public/**").permitAll()
                .requestMatchers("/admin/**").hasRole("ADMIN")
                .requestMatchers("/employees/**").hasRole("USER")
                .anyRequest().denyAll())
            .formLogin(Customizer.withDefaults())
            .build();
    }
}

